def clean(df):
    df = df.copy()
    df = df.drop_duplicates()

    for col in df.columns:
        if df[col].dtype == object or str(df[col].dtype) == 'string':
            df[col] = df[col].astype('string').str.strip()

    cat_map = {
        'accessories': 'Accessories',
        'office supplies': 'Office Supplies',
        'Furnture': 'Furniture'
    }
    if 'Category' in df.columns:
        df['Category'] = df['Category'].replace(cat_map)

    if 'Date' in df.columns:
        parsed = pd.to_datetime(df['Date'], errors='coerce')
        df['Date'] = parsed.dt.strftime('%Y-%m-%d').where(parsed.notna(), df['Date'])

    for col in ['Order_ID', 'Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    return df


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    result = d.groupby('Category', dropna=True)['Price'].mean()
    return {str(k): float(v) for k, v in result.items()}
